-- Correction based on Kadane's algorithm:
-- We need to fold over the list, maintaining (current_max_ending_here, overall_max_so_far).
-- The initial state should be based on the first element.

def task_code' (sequence : List Int) (h_precond : task_code_precond (sequence)) : Int :=
    match sequence with
    | [] => 0
    | x :: xs =>
        let initialState := (x, x) -- (cur, maxSoFar)
        let (_, maxSoFar) :=
          xs.foldl (fun (cur_acc : Int × Int) (x : Int) =>
            let (cur_old, maxSoFar_old) := cur_acc
            -- cur = max(element, cur + element)
            let new_cur := max x (cur_old + x)
            -- maxSoFar = max(maxSoFar, cur)
            let new_maxSoFar := max maxSoFar_old new_cur
            (new_cur, new_maxSoFar)
          ) initialState xs
        maxSoFar

def task_code (sequence : List Int) (h_precond : task_code_precond (sequence)) : Int :=
  task_code' sequence h_precond

