let n := nums.length
let all_subsets := List.range (2 ^ n)
let subsets := all_subsets.map fun mask =>
  (List.range n).foldr (fun i acc =>
    if (mask >> i) .&. 1 = 1 then nums[i] :: acc else acc
  ) []

let nonEmptySubsets := subsets.filter (fun s => s ≠ [])

